using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BondDuplicatorOmenData", menuName = "Data/Battle/Omens System/Omen Data/Hevelius/BondDuplicator Omen Data")]
public class BondDuplicatorOmenData : OnStartOfBattleOmenData
{
	[Header("Link Duplicate Omen")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	[NonSerialized]
	private Action<HeveliusLinkEffect, int, GameObject, GameObject> linkDuplicateOmenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		base.Initialize(omenInstance);
		linkDuplicateOmenAction = delegate(HeveliusLinkEffect linkEffect, int effectAmount, GameObject effectOwner, GameObject source)
		{
			if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) && currentCompanions.ActiveCompanions.Count == 2)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				currentCompanions.GetOtherCompanion(effectOwner).GetComponent<UnitEffects>().AddEffect(linkEffect, effectAmount);
			}
		};
		ReferenceSingleton<HeveliusOmensHandler>.Instance.LinkDuplicateAction = linkDuplicateOmenAction;
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		ReferenceSingleton<HeveliusOmensHandler>.Instance.LinkDuplicateAction = null;
	}

	public override string OmenConvertedDescription()
	{
		string localizedString = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(base.omenIDDescription);
		string text = base.OmenConvertedDescription();
		return localizedString + "\n" + text;
	}
}
